//! The Matter data model, as the IDL describes it: the names and types of
//! every cluster's attributes and commands, generated by `build.rs`.

/// A cluster.
#[derive(Debug)]
pub struct ClusterSchema {
    pub id: u32,
    pub name: &'static str,
    pub attributes: &'static [AttrSchema],
    pub commands: &'static [CmdSchema],
}

impl ClusterSchema {
    pub fn attribute(&self, id: u32) -> Option<&'static AttrSchema> {
        self.attributes.iter().find(|a| a.id == id)
    }

    pub fn command(&self, id: u32) -> Option<&'static CmdSchema> {
        self.commands.iter().find(|c| c.id == id)
    }

    /// A command answering with `id`.
    pub fn response(&self, id: u32) -> Option<&'static RespSchema> {
        self.commands
            .iter()
            .filter_map(|c| c.response.as_ref())
            .find(|r| r.id == id)
    }

    pub fn attribute_named(&self, name: &str) -> Option<&'static AttrSchema> {
        self.attributes
            .iter()
            .find(|a| a.name.eq_ignore_ascii_case(name))
    }

    pub fn command_named(&self, name: &str) -> Option<&'static CmdSchema> {
        self.commands
            .iter()
            .find(|c| c.name.eq_ignore_ascii_case(name))
    }
}

/// An attribute.
#[derive(Debug)]
pub struct AttrSchema {
    pub id: u32,
    pub name: &'static str,
    pub value: ValueSchema,
    pub writable: bool,
    /// Written with a timed interaction only.
    pub timed: bool,
}

/// A command: its fields, and its response unless it answers with a status.
#[derive(Debug)]
pub struct CmdSchema {
    pub id: u32,
    pub name: &'static str,
    pub fields: &'static [FieldSchema],
    pub response: Option<RespSchema>,
    /// Invoked with a timed interaction only.
    pub timed: bool,
}

/// A command response.
#[derive(Debug)]
pub struct RespSchema {
    pub id: u32,
    pub name: &'static str,
    pub fields: &'static [FieldSchema],
}

/// A field of a struct or command, by its context tag.
#[derive(Debug)]
pub struct FieldSchema {
    pub tag: u32,
    pub name: &'static str,
    pub value: ValueSchema,
}

/// What a value is: its type, as the IDL names it too (`temperature`,
/// `percent`, …, which say its unit), and whether it is a list of them, may
/// be null or may be missing.
#[derive(Debug)]
pub struct ValueSchema {
    pub ty: TypeRef,
    pub idl: &'static str,
    pub list: bool,
    pub nullable: bool,
    pub optional: bool,
}

/// A value's type.
#[derive(Debug, Clone, Copy)]
pub enum TypeRef {
    Bool,
    /// An unsigned integer of this many bits.
    UInt(u8),
    /// A signed integer of this many bits.
    Int(u8),
    Float,
    Double,
    Text,
    Octets,
    Enum(&'static EnumSchema),
    Bitmap(&'static BitmapSchema),
    Struct(&'static StructSchema),
}

#[derive(Debug)]
pub struct EnumSchema {
    pub name: &'static str,
    pub values: &'static [(u64, &'static str)],
}

impl EnumSchema {
    pub fn name_of(&self, value: u64) -> Option<&'static str> {
        self.values
            .iter()
            .find(|(v, _)| *v == value)
            .map(|(_, name)| *name)
    }

    pub fn value_of(&self, name: &str) -> Option<u64> {
        self.values
            .iter()
            .find(|(_, n)| n.eq_ignore_ascii_case(name))
            .map(|(v, _)| *v)
    }
}

/// A bitmap: the mask of each of its named bits (or fields of bits).
#[derive(Debug)]
pub struct BitmapSchema {
    pub name: &'static str,
    pub bits: &'static [(u64, &'static str)],
}

#[derive(Debug)]
pub struct StructSchema {
    pub name: &'static str,
    pub fields: &'static [FieldSchema],
}

/// The clusters, by ID.
mod data {
    use super::*;

    include!(concat!(env!("OUT_DIR"), "/schema.rs"));
}

/// The cluster with `id`, if the IDL has it.
pub fn cluster(id: u32) -> Option<&'static ClusterSchema> {
    data::CLUSTERS
        .binary_search_by_key(&id, |c| c.id)
        .ok()
        .map(|i| &data::CLUSTERS[i])
}

/// The cluster named `name`, in any case.
pub fn cluster_named(name: &str) -> Option<&'static ClusterSchema> {
    data::CLUSTERS
        .iter()
        .find(|c| c.name.eq_ignore_ascii_case(name))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_the_on_off_cluster() {
        let on_off = cluster(0x0006).unwrap();
        assert_eq!(on_off.name, "OnOff");
        assert_eq!(on_off.attribute(0).unwrap().name, "OnOff");
        assert_eq!(on_off.command(2).unwrap().name, "Toggle");
        assert_eq!(cluster_named("onoff").unwrap().id, 0x0006);
    }

    #[test]
    fn describes_a_command_with_fields_and_a_struct() {
        let level = cluster(0x0008).unwrap();
        let move_to = level.command_named("MoveToLevel").unwrap();
        let names: alloc::vec::Vec<_> = move_to.fields.iter().map(|f| f.name).collect();
        assert_eq!(names[..2], ["Level", "TransitionTime"]);
        assert!(matches!(move_to.fields[0].value.ty, TypeRef::UInt(8)));
        assert!(move_to.fields[1].value.nullable);

        let thermostat = cluster(0x0201).unwrap();
        let mode = thermostat.attribute_named("SystemMode").unwrap();
        assert!(mode.writable);
        let TypeRef::Enum(e) = mode.value.ty else {
            panic!("SystemMode is not an enum");
        };
        assert_eq!(e.name_of(4), Some("Heat"));
        assert_eq!(e.value_of("cool"), Some(3));

        let local = thermostat.attribute_named("LocalTemperature").unwrap();
        assert_eq!(local.value.idl, "temperature");
        assert!(matches!(local.value.ty, TypeRef::Int(16)));
    }
}
